def S(n):
    s = 0
    while n:
        s += n % 10
        n //= 10
    return s

# Test small n to find the smallest n such that S(k) is divisible by 11 for k in [n, n+37]
for n in range(1, 10):
    found = False
    for k in range(n, n + 38):
        if S(k) % 11 == 0:
            found = True
            break
    if found:
        print(f"Smallest n found is: {n}")
        break
else:
    print("No small n found yet.")
